          'La suppression de votre compte entraînera la suppression de toutes vos informations de compte et de votre portefeuille Schatz.\n\nVeuillez vous assurer de retirer tous les fonds de votre portefeuille avant de supprimer votre compte.\n\nVous disposez de 30 jours pour vérifier à nouveau votre portefeuille avant sa suppression définitive de notre base de données.',
      'it':
          'L\'eliminazione del tuo account comporterà la cancellazione di tutte le informazioni relative al tuo account e del tuo portafoglio Schatz.\n\nAssicurati di rimuovere tutti i fondi dal tuo portafoglio prima di eliminare l\'account.\n\nHai 30 giorni di tempo per rivalutare il tuo portafoglio prima che venga eliminato definitivamente dal nostro database.',
      'ja':
          'アカウントを削除すると、アカウント情報とSchatzウォレットの内容がすべて削除されます。\n\nアカウントを削除する前に、ウォレット内の資金をすべて引き出してください。\n\nウォレットはデータベースから完全に削除されるまで30日間ありますので、その間にウォレットの内容を再確認してください。',
